INSERT INTO `data_quest_moi` (`id`,`name`,`npcrcv`,`npcres`,`lv`,`mainsub`,`content`,`scontent`,`rescontent`,`idItemget`,`idMonskill`,`type`,`nitemget`,`nmonskill`,`gold`,`exp`,`potiongift`,`npotion`,`itemgift`,`deltaLv`,`infogift`,`infofinish`,`pactive`,`luong`,`luongLock`) VALUES
(901,'Thức giấc ở Pallet',5,32000,1,0,'1Xatu: ...Cháu tỉnh rồi. Đây là Pallet, làng của những Pokémon hiền lành.>1Xatu: Ta là Xatu, trưởng làng. Ta sẽ chỉ cháu những điều đầu tiên.','Nói chuyện với Xatu ở Pallet','32000','32000','32000',3,'32000','32000',323,1292,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Xatu ở Pallet|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|1.292 EXP, 323 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Đi chào Kecleon ở tiệm tạp hoá trước nhé.',0,0,2),
(902,'Chào Kecleon',1,32000,1,0,'1Kecleon: Hí hí, khách mới! Tiệm tôi có Thuốc hồi máu và Ether. Hết máu thì ghé nhé.','Nói chuyện với Kecleon ở Pallet','32000','32000','32000',3,'32000','32000',323,1292,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Kecleon ở Pallet|Địa điểm:|Pallet|NPC:|Kecleon|Phần thưởng:|1.292 EXP, 323 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Kecleon: Giờ tập đánh một chút. Ra đồng đi bạn nhỏ.',0,0,2),
(903,'Bài học tấn công',5,5,2,0,'1Xatu: Chạm vào quái để đánh. Hạ 20 Caterpie ngoài đồng.','Hạ 20 Caterpie ở Pallet','1Xatu: Giỏi lắm! Lên cấp là mạnh hơn đấy.','32000','2',0,'32000','20',353,1735,'32000','32000','32000',0,'Nhiệm vụ:|Hạ 20 Caterpie|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|1.735 EXP, 353 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Giỏi lắm! Lên cấp là mạnh hơn đấy.',0,0,2),
(904,'Bình thuốc đầu tiên',5,32000,2,0,'1Chansey: Chan-sey! Máu thấp thì dùng thuốc trong túi nhé. Chị cho em vài bình.','Nói chuyện với Chansey ở Pallet','32000','32000','32000',3,'32000','32000',353,1735,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Chansey ở Pallet|Địa điểm:|Pallet|NPC:|Chansey|Phần thưởng:|1.735 EXP, 353 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Chansey: Nhớ hồi máu trước khi đánh quái mạnh.',0,0,2),
(905,'Bài học chiêu thức',5,5,3,0,'1Xatu: Dùng chiêu thức (phím tắt) để đánh mạnh hơn. Hạ 20 Ekans.','Hạ 20 Ekans ở Pallet','1Xatu: Chiêu thức hồi chiêu, xen kẽ với đòn thường.','32000','5',0,'32000','20',384,2370,'32000','32000','32000',0,'Nhiệm vụ:|Hạ 20 Ekans|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|2.370 EXP, 384 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Chiêu thức hồi chiêu, xen kẽ với đòn thường.',0,0,2),
(906,'Gặp Machamp thợ chế tạo',2,32000,3,0,'1Machamp: Khà khà! Ta lo đồ đạc. Nâng cấp, chế tạo, khảm ngọc: tìm ta.','Nói chuyện với Machamp ở Pallet','32000','32000','32000',3,'32000','32000',384,2370,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Machamp ở Pallet|Địa điểm:|Pallet|NPC:|Machamp|Phần thưởng:|2.370 EXP, 384 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Machamp: Mặc thử món đồ ta tặng đi.',0,0,2),
(907,'Mặc trang bị',5,32000,4,0,'1Xatu: Mở túi, chọn món đồ rồi chọn Mặc.','Mặc 1 món trang bị ở Pallet','32000','32000','32000',3,'32000','32000',383,3131,'32000','32000','1001,1001,1001,1001,1001,0',0,'Nhiệm vụ:|Mặc 1 món trang bị|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|3.131 EXP, 383 xu, 2 lượng khoá, Ruy băng sơ cấp','Nhiệm vụ hoàn thành|Xatu: Ra dáng rồi đấy!',0,0,2),
(908,'Thử sức ngoài đồng',5,5,4,0,'1Xatu: Đi xa hơn một chút. Hạ 20 Bellsprout.','Hạ 20 Bellsprout ở Pallet','1Xatu: Cháu tiến bộ nhanh lắm.','32000','7',0,'32000','20',383,3131,'32000','32000','32000',0,'Nhiệm vụ:|Hạ 20 Bellsprout|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|3.131 EXP, 383 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Cháu tiến bộ nhanh lắm.',0,0,2),
(909,'Sổ tay Pokédex',5,32000,5,0,'1Xatu: Mỗi loài cháu gặp sẽ được ghi vào Pokédex. Thử gặp Ekans đi.','Ghi Ekans vào Pokédex ở Pallet','32000','32000','32000',3,'32000','32000',414,4269,'32000','32000','32000',0,'Nhiệm vụ:|Ghi Ekans vào Pokédex|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|4.269 EXP, 414 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Sổ có trang đầu tiên rồi.',0,0,2),
(910,'Lời hứa với Xatu',5,32000,5,0,'1Xatu: ...Cháu đã sẵn sàng. Ngôi sao rơi đêm qua đang chờ cháu tìm hiểu.','Nói chuyện với Xatu ở Pallet','32000','32000','32000',3,'32000','32000',414,4269,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Xatu ở Pallet|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|4.269 EXP, 414 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Đi đi. Ta sẽ dõi theo.',0,0,2),
(1001,'Tỉnh giấc dưới mưa sao',5,32000,1,0,'1Xatu: ...Ta đã thấy cháu trong giấc mơ đêm qua.>1Xatu: Một ngôi sao rơi xuống đồng cỏ, và cháu nằm ngay chỗ nó rơi.>0Cháu... không nhớ gì cả.>1Xatu: Không sao. Ký ức sẽ về khi cháu bước đi.','Nói chuyện với Xatu ở Pallet','32000','32000','32000',3,'32000','32000',807,3230,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Xatu ở Pallet|Địa điểm:|Pallet|NPC:|Xatu|Phần thưởng:|3.230 EXP, 807 xu, 1 lượng khoá','Nhiệm vụ hoàn thành|Xatu: Hãy làm quen với Pallet trước. Snorlax ở cuối làng sẽ cho cháu ăn sáng.',0,0,1),
(1002,'Bữa sáng của ông Snorlax',8,32000,1,0,'1Snorlax: Oáp... Xatu bảo có đứa nhỏ rơi từ trời xuống à?>1Snorlax: Ăn đi đã, bụng no thì đầu mới sáng.','Nói chuyện với Snorlax ở Pallet','32000','32000','32000',3,'32000','32000',1009,4038,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Snorlax ở Pallet|Địa điểm:|Pallet|NPC:|Snorlax|Phần thưởng:|4.038 EXP, 1.009 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Snorlax: Ngon chứ? Quả Oran vườn ông đấy. Mà... vườn ông đang có chuyện.',0,0,2),
