(1081,'Bữa tiệc trên boong',6,32000,26,0,'1Persian: Hừm. Bữa tiệc tầm thường quá. Ít ra cái vòng cổ ngọc của ta làm nó sáng hơn.>1Persian: ...Khoan. Vòng cổ của ta đâu?!','Nói chuyện với Persian ở Tàu S.S. Anne','32000','32000','32000',3,'32000','32000',880,71051,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Persian ở Tàu S.S. Anne|Địa điểm:|Tàu S.S. Anne|NPC:|Persian|Phần thưởng:|71.051 EXP, 880 xu, 1 lượng khoá','Nhiệm vụ hoàn thành|Persian: Lại nữa! Cưng tìm giúp ta. Lần này ta trả công gấp đôi.',0,0,1),
(1082,'Hỏi chuyện Kangaskhan',9,32000,26,0,'1Kangaskhan: Kangaskhan đang trông lũ trẻ ở góc tiệc. Hỏi xem cô có thấy gì không.','Nói chuyện với Kangaskhan ở Tàu S.S. Anne','32000','32000','32000',3,'32000','32000',1100,88814,'32000','32000','32000',0,'Nhiệm vụ:|Nói chuyện với Kangaskhan ở Tàu S.S. Anne|Địa điểm:|Tàu S.S. Anne|NPC:|Kangaskhan|Phần thưởng:|88.814 EXP, 1.100 xu, 2 lượng khoá','Nhiệm vụ hoàn thành|Kangaskhan: Ôi con, cô thấy một Murkrow bay qua cửa sổ lúc đèn tắt. Nó ngậm gì đó lấp lánh.',0,0,2),
